import AppKit
import AVFoundation
import Foundation
import SwiftRender
import SwiftRenderKit
import SwiftUI

public let swiftRenderVersion = "0.10.0"

// MARK: - Scene registry
//
// The executable passes its build-time registry (generated by SceneRegistryPlugin:
// every `public struct X` conforming to a scene protocol, registered as "X") to
// `SwiftRenderCommand.main(scenes:)`.

@MainActor var sceneRunners: [String: SceneRunner] = [:]

/// Entry point for any executable that hosts scenes:
///
///     // Sources/<YourCLI>/main.swift
///     import SwiftRenderTool
///     await SwiftRenderCommand.main(scenes: generatedSceneRunners)
public enum SwiftRenderCommand {
    @MainActor
    public static func main(scenes: [String: SceneRunner],
                            arguments: [String] = CommandLine.arguments) async {
        // Built-in template scenes (e.g. AppleLaunch) are available to every project;
        // a project scene with the same name wins.
        sceneRunners = builtinSceneRunners().merging(scenes) { _, project in project }
        do {
            try await run(arguments)
        } catch {
            fputs("[swift-render] error: \(error)\n", stderr)
            exit(1)
        }
        exit(0)
    }
}

// MARK: - CLI

struct CLIArgs {
    var subcommand: String          // render | list | preview
    var sceneName: String = ""
    var duration: Double? = nil     // nil → use scene default
    var fps: Int = 60
    var aspect: AspectPreset = .landscape16x9
    var size: CGSize? = nil
    var scale: CGFloat = 1.0
    var out: String = "out/render.mp4"
    var audio: String? = nil
    var at: [Double] = [0]      // `frame` subcommand: one or more timestamps
    var preview = false
    var jobs = 1
    var open = false
    var kind = "render"         // `new`: render | audio
    var rangeStart: Double? = nil
    var rangeEnd: Double? = nil
    var props: String? = nil
    var postFX: Bool = true
    var cols: Int = 5
    var rows: Int = 3
    var snapshot: String? = nil     // `preview`: write the window to PNG after layout, then exit
    var progress: String? = nil     // `render --progress json`: machine-readable progress on stderr
    var knobs: String? = nil        // `--knobs file.json`: overrides used instead of the project's knob file
    var json = false                // `list --json`
}

/// A command-line mistake: printed (with usage when `showUsage`) and exited with `code`.
struct CLIUsageError: Error, CustomStringConvertible, Equatable {
    var description: String
    var code: Int32 = 64
    var showUsage = false
}

func parseArgs(_ argv: [String]) -> CLIArgs {
    do {
        return try parseCLIArgs(argv)
    } catch let e as CLIUsageError {
        fputs(e.description + (e.description.hasSuffix("\n") ? "" : "\n"), stderr)
        if e.showUsage { fputs("\n", stderr); printUsage() }
        exit(e.code)
    } catch {
        fputs("\(error)\n", stderr)
        exit(64)
    }
}

/// Valued options of the scene subcommands. A valued option must be followed by its
/// value: `render X --out` (a typo) is an error, never "--out = the working directory".
let cliValuedOptions: Set<String> = [
    "--duration", "--fps", "--aspect", "--width", "--height", "--scale", "--out", "--audio", "--at",
    "--jobs", "--kind", "--props", "--cols", "--rows", "--snapshot", "--progress", "--knobs", "--range",
]

/// Parses and validates scene-subcommand arguments. Throws `CLIUsageError` (exit 64)
/// for a missing or malformed value instead of guessing.
func parseCLIArgs(_ argv: [String]) throws -> CLIArgs {
    if argv.count < 2 {
        throw CLIUsageError(description: "Missing subcommand.", code: 1, showUsage: true)
    }

    let sub = argv[1]
    var args = CLIArgs(subcommand: sub)

    if sub == "list" || sub == "smoke" || sub == "--help" || sub == "-h" || sub == "--version" {
        args.json = argv.dropFirst(2).contains("--json")
        return args
    }

    guard argv.count >= 3, !argv[2].hasPrefix("--") else {
        throw CLIUsageError(description: "Missing scene name. Try: swift-render list", code: 1)
    }
    args.sceneName = argv[2]

    func number(_ k: String, _ v: String) throws -> Double {
        guard let d = Double(v), d.isFinite else { throw CLIUsageError(description: "\(k) expects a number, got '\(v)'") }
        return d
    }
    func integer(_ k: String, _ v: String, _ range: ClosedRange<Int>) throws -> Int {
        guard let n = Int(v), range.contains(n) else {
            throw CLIUsageError(description: "\(k) expects a whole number in \(range.lowerBound)…\(range.upperBound), got '\(v)'")
        }
        return n
    }

    var i = 3
    while i < argv.count {
        let k = argv[i]
        var v = ""
        if cliValuedOptions.contains(k) {
            guard i + 1 < argv.count, !argv[i + 1].hasPrefix("--") else {
                throw CLIUsageError(description: "\(k) needs a value")
            }
            v = argv[i + 1]
        }
        switch k {
        case "--duration":
            let d = try number(k, v)
            guard d > 0 else { throw CLIUsageError(description: "--duration must be > 0 seconds, got '\(v)'") }
            args.duration = d; i += 2
        case "--fps":      args.fps = try integer(k, v, 1...240); i += 2
        case "--aspect":
            guard let a = AspectPreset(rawValue: v) else {
                throw CLIUsageError(description: "--aspect expects one of \(AspectPreset.allCases.map(\.rawValue).joined(separator: ", ")), got '\(v)'")
            }
            args.aspect = a; i += 2
        case "--width":
            let w = try integer(k, v, 16...16384)
            let curH = Int(args.size?.height ?? 1080)
            args.size = CGSize(width: w, height: curH)
            i += 2
        case "--height":
            let h = try integer(k, v, 16...16384)
            let curW = Int(args.size?.width ?? 1920)
            args.size = CGSize(width: curW, height: h)
            i += 2
        case "--scale":
            let sc = try number(k, v)
            guard sc > 0, sc <= 16 else { throw CLIUsageError(description: "--scale must be in (0, 16], got '\(v)'") }
            args.scale = CGFloat(sc); i += 2
        case "--out":
            do { try OutputPath.validate(v, flag: "--out") } catch { throw CLIUsageError(description: "\(error)") }
            args.out = v; i += 2
        case "--audio":    args.audio = v; i += 2
        case "--at":
            let parts = v.split(separator: ",").map { $0.trimmingCharacters(in: .whitespaces) }
            var ts: [Double] = []
            for p in parts {
                guard let d = Double(p), d.isFinite, d >= 0 else {
                    throw CLIUsageError(description: "--at expects seconds ≥ 0 (e.g. 1,2.5), got '\(v)'")
                }
                ts.append(d)
            }
            guard !ts.isEmpty else { throw CLIUsageError(description: "--at needs a value") }
            args.at = ts; i += 2
        case "--preview":  args.preview = true; i += 1
        case "--jobs":
            guard v == "auto" || (Int(v).map { $0 >= 1 } ?? false) else {
                throw CLIUsageError(description: "--jobs expects a count ≥ 1 or 'auto', got '\(v)'")
            }
            args.jobs = resolveJobs(v); i += 2
        case "--open":     args.open = true; i += 1
        case "--kind":     args.kind = v; i += 2
        case "--props":    args.props = v; i += 2
        case "--no-postfx": args.postFX = false; i += 1
        case "--cols":     args.cols = try integer(k, v, 1...64); i += 2
        case "--rows":     args.rows = try integer(k, v, 1...64); i += 2
        case "--snapshot":
            do { try OutputPath.validate(v, flag: "--snapshot") } catch { throw CLIUsageError(description: "\(error)") }
            args.snapshot = v; i += 2
        case "--progress":
            guard v == "json" else { throw CLIUsageError(description: "--progress takes 'json'") }
            args.progress = v; i += 2
        case "--knobs":    args.knobs = v; i += 2
        case "--range":
            let parts = v.split(separator: ":", omittingEmptySubsequences: false).map { Double($0) }
            guard parts.count == 2, let a = parts[0], let b = parts[1], a.isFinite, b.isFinite, a >= 0, b > a else {
                throw CLIUsageError(description: "--range expects a:b seconds with 0 ≤ a < b, got '\(v)'")
            }
            args.rangeStart = a; args.rangeEnd = b
            i += 2
        default:
            throw CLIUsageError(description: "Unknown option: \(k)", showUsage: true)
        }
    }
    return args
}

func printUsage() {
    fputs("""
    swift-render — programmatic motion graphics in Swift

    USAGE:
      swift-render new <Scene> [--kind audio]  Scaffold a scene (Sources/SwiftRenderScenes, or swift-render.json scenesDir)
      swift-render check <Scene>            Contact sheet + blank-frame scan + audio report
      swift-render preview <Scene>          Live window: scrub, play/pause, frame-step, audio
      swift-render render <Scene> [opts]    Render a scene to MP4
      swift-render frame <Scene> --at <t>   Render frame(s) to PNG; --at 1,2.5,4 for several
      swift-render props <Scene>            Print a scene's default props as JSON
      swift-render contact <Scene>           Render a grid contact sheet to PNG
      swift-render audio <Scene> --out x.wav Export a scene's Score as WAV
      swift-render captions <Scene> --out x.srt  Export voiceover captions (.srt or .vtt)
      swift-render smoke                    Render one frame of every scene; fail on errors or swishes (CI)
      swift-render list [--json]            List available scenes (--json: SceneSummary array)
      swift-render info <Scene> [--json]    Clips, knobs, score events, captions (agent/editor metadata)

    LAUNCH FILMS:
      swift-render launch [path] [--out f]  Scan a Swift codebase and render an Apple-style launch film
      swift-render init [path]              Scaffold a Launch/ package (your own scenes + CLI) in a codebase

    EDITOR & REVIEW:
      swift-render serve                    Render host for swift-render Studio (JSON lines on stdio)
      swift-render review list|show|add|reply|status …   Timecoded review comments (see docs/review-loop.md)
      swift-render --help                   Show this help
      swift-render --version                Print version

    SCENE OPTIONS:
      --duration <seconds>     Override scene's default duration
      --fps <n>                Frame rate (default 60)
      --aspect 16:9|9:16|1:1   Output aspect (default 16:9)
      --width <px>             Custom width (overrides --aspect)
      --height <px>            Custom height
      --scale <n>              Display scale (default 1.0)
      --out <path>             Output mp4 path (default out/render.mp4)
      --audio <path>           Optional audio file to mux into the output
      --range <a:b>            Render only seconds a..b (picture only; timing matches the full render)
      --at <t>                 Frame timestamp for the `frame` subcommand
      --props <file.json>      JSON props for parameterized scenes
      --cols/--rows <n>        Contact sheet grid (default 5×3)
      --no-postfx              Disable the global grain+vignette pass
      --jobs <n|auto>          Render in n parallel processes and stitch (auto = half the cores)
      --preview                Half resolution, 30 fps — fast look at motion
      --open                   Open the result when done
      --snapshot <png>         `preview` only: save the window to PNG and exit (CI/agents)
      --knobs <file.json>      Knob overrides for this run, used instead of .swift-render/knobs/<Scene>.json
      --progress json          `render` only: {"progress":{"frame":i,"total":n,"fps":f}} lines on stderr

    PREVIEW KEYS:
      space play/pause · ←/→ one frame · ⇧←/⇧→ one second · home start · esc/⌘W close

    LOOP:
      swift-render new MyFilm && swift-render check MyFilm
      swift-render preview MyFilm
      swift-render render MyFilm --preview --open
      swift-render render MyFilm --out out/myfilm.mp4

    EXAMPLES:
      swift-render render LogoReveal --out out/hero.mp4
      swift-render render LaunchReel --aspect 16:9 --out out/reel.mp4
      swift-render render NotchRecording --aspect 9:16 --out out/notch-vert.mp4
      swift-render render LogoReveal --audio music/intro.m4a --out out/hero-audio.mp4

    """, stderr)
}

// MARK: - Run

@MainActor
func run(_ argv: [String]) async throws {
    registerBundledFonts()

    // Subcommands with their own argument shapes.
    if argv.count >= 2 {
        let tail = Array(argv.dropFirst(2))
        switch argv[1] {
        case "serve":  try await runServe(tail); return
        case "info":   try runInfo(tail); return
        case "launch": try await runLaunch(tail); return
        case "init":   try runInit(tail); return
        case "review": try runReview(tail); return
        default: break
        }
    }

    let args = parseArgs(argv)

    switch args.subcommand {
    case "list":
        let names = sceneRunners.keys.sorted()
        if args.json {
            let enc = JSONEncoder()
            enc.outputFormatting = [.prettyPrinted, .sortedKeys, .withoutEscapingSlashes]
            let summaries = names.map { sceneRunners[$0]!.summary(name: $0) }
            print(String(decoding: try enc.encode(summaries), as: UTF8.self))
            return
        }
        for name in names {
            let runner = sceneRunners[name]!
            print("  \(name)  (default: \(runner.defaultDuration)s)")
        }
        return
    case "--help", "-h":
        printUsage()
        return
    case "--version":
        print(swiftRenderVersion)
        return
    case "smoke":
        warnIfShadersStale()
        if !runSmoke(scale: 0.2) { exit(1) }
        return
    case "new":
        do {
            let url = try scaffoldScene(name: args.sceneName, kind: args.kind)
            print("[swift-render] created \(url.path)")
            let cli = Project.discover()?.config.product ?? "swift-render"
            print("[swift-render] it is auto-registered — next: swift run \(cli) check \(args.sceneName)")
        } catch {
            fputs("[swift-render] \(error.localizedDescription)\n", stderr); exit(1)
        }
        return
    case "render", "frame", "props", "contact", "audio", "check", "preview", "captions":
        warnIfShadersStale()
    default:
        fputs("Unknown subcommand: \(args.subcommand)\n", stderr)
        printUsage()
        exit(1)
    }

    guard let runner = sceneRunners[args.sceneName] else {
        fputs("Unknown scene: \(args.sceneName)\n", stderr)
        fputs("Try: swift run \(Project.discover()?.config.product ?? "swift-render") list\n", stderr)
        exit(1)
    }
    // Knob overrides from .swift-render/knobs/<Scene>.json apply to every render path;
    // --knobs swaps in another file (Studio: "export with the live values").
    KnobStore.shared.load(scene: args.sceneName, project: Project.discover())
    if let knobsPath = args.knobs {
        do {
            let data = try Data(contentsOf: URL(fileURLWithPath: knobsPath))
            KnobStore.shared.set(try JSONDecoder().decode([String: KnobValue].self, from: data))
        } catch {
            fputs("[swift-render] cannot read --knobs \(knobsPath): \(error.localizedDescription)\n", stderr)
            exit(1)
        }
    }

    if args.subcommand == "props" {
        if let template = runner.propsTemplate {
            print(template())
        } else {
            fputs("\(args.sceneName) takes no props\n", stderr)
            exit(1)
        }
        return
    }

    let duration = args.duration ?? runner.durationFor(args.props.map { URL(fileURLWithPath: $0) })
    let size = args.size ?? args.aspect.size
    let audioURL = args.audio.map { URL(fileURLWithPath: $0) }
    let propsURL = args.props.map { URL(fileURLWithPath: $0) }
    // Props from `launch <app>` keep icon/screenshot paths relative to the scanned app root.
    if let propsURL, let root = PropsAssets.scannedRoot(forPropsFile: propsURL),
       !AssetPaths.extraSearchPaths.contains(root) {
        AssetPaths.extraSearchPaths.append(root)
    }

    // Precedence: explicit --audio > scene-declared Score > silence.
    let audioSource: AudioSource
    if let audioURL {
        audioSource = .file(audioURL)
    } else if let score = runner.soundtrack(duration, propsURL) {
        audioSource = .score(score)
    } else {
        audioSource = .none
    }

    if args.subcommand == "captions" {
        guard let score = runner.soundtrack(duration, propsURL) else {
            fputs("\(args.sceneName) declares no soundtrack\n", stderr)
            exit(1)
        }
        let track = CaptionTrack(score)
        guard !track.cues.isEmpty else {
            fputs("\(args.sceneName) has no speak(...) lines\n", stderr)
            exit(1)
        }
        let outPath = args.out == "out/render.mp4" ? "out/\(args.sceneName).srt" : args.out
        let body = outPath.lowercased().hasSuffix(".vtt") ? track.vtt() : track.srt()
        let url = URL(fileURLWithPath: outPath)
        try FileManager.default.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
        try body.write(to: url, atomically: true, encoding: .utf8)
        print("[swift-render] \(track.cues.count) captions → \(outPath)")
        return
    }

    if args.subcommand == "preview" {
        try runPreview(runner: runner, name: args.sceneName, duration: duration, size: size,
                       fps: args.fps, audio: audioSource, propsURL: propsURL,
                       postFX: args.postFX && !runner.ownsPostFX, snapshot: args.snapshot)
        return
    }

    if args.subcommand == "audio" {
        guard let score = runner.soundtrack(duration, propsURL) else {
            fputs("\(args.sceneName) declares no soundtrack\n", stderr)
            exit(1)
        }
        let outPath = args.out == "out/render.mp4" ? "out/score.wav" : args.out
        try ScoreSynth.writeWAV(score, to: URL(fileURLWithPath: outPath))
        print(String(format: "[swift-render] score %.2fs (%d events) → %@",
                     score.duration, score.events.count, outPath))
        return
    }

    let isPreview = args.preview && args.subcommand == "render"
    let config = Recorder.Config(
        fps: isPreview ? min(args.fps, 30) : args.fps,
        size: size,
        scale: isPreview ? args.scale * 0.5 : args.scale,
        postFX: args.postFX
    )
    let recorder = Recorder(config: config)

    if args.subcommand == "contact" || args.subcommand == "check" {
        let isCheck = args.subcommand == "check"
        let defaultOut = isCheck ? "out/check-\(args.sceneName).png" : "out/contact.png"
        let outURL = URL(fileURLWithPath: args.out == "out/render.mp4" ? defaultOut : args.out)
        let cols = isCheck && args.cols == 5 && args.rows == 3 ? 4 : args.cols
        let rows = isCheck && args.cols == 5 && args.rows == 3 ? 4 : args.rows
        // Synthesize once: the report and an audio-reactive scene's track share the samples.
        var checkAudio = CheckAudio.none
        var track = AudioTrack.silent
        switch audioSource {
        case .score(let score):
            if isCheck || runner.reactsToAudio {
                let (l, r) = ScoreSynth.render(score)
                checkAudio = .score(score, left: l, right: r)
                if runner.reactsToAudio {
                    track = try AudioAnalyzer.analyze(samples: mixdown(l, r), sampleRate: scoreSampleRate, fps: args.fps)
                }
            }
        case .file(let url):
            checkAudio = .file(url)
            if runner.reactsToAudio { track = try AudioAnalyzer.analyze(url: url, fps: args.fps) }
        case .none:
            break
        }
        let scene = try PreparedScene(name: args.sceneName, runner: runner, duration: duration, size: size,
                                      fps: args.fps, postFX: args.postFX, propsURL: propsURL, track: track)
        guard isCheck else {
            _ = try renderContactSheet(scene, cols: cols, rows: rows, to: outURL)
            print("[swift-render] contact sheet \(cols)×\(rows) → \(outURL.path)")
            return
        }
        let result = try runCheck(scene, audio: checkAudio, cols: cols, rows: rows, contact: outURL)
        print("[swift-render] contact sheet \(cols)×\(rows) → \(outURL.path)")
        print(result.report.joined(separator: "\n"))
        print("[swift-render] report → \(result.reportURL.path)")
        return
    }

    if args.subcommand == "frame" {
        let base = args.out == "out/render.mp4" ? "out/frame.png" : args.out
        for t in args.at {
            let outPath = args.at.count == 1 ? base
                : (base as NSString).deletingPathExtension + String(format: "_%.2f.png", t)
            try runner.frame(recorder, URL(fileURLWithPath: outPath), t, duration, audioSource, propsURL)
            print("[swift-render] frame t=\(t)s → \(outPath)")
        }
        return
    }

    let outURL = URL(fileURLWithPath: args.out)
    if args.rangeStart != nil && args.audio != nil {
        fputs("[swift-render] note: --range renders are picture-only; render the full scene to mux audio\n", stderr)
    }
    let startTime = args.rangeStart ?? 0
    let endTime = args.rangeEnd ?? duration
    let totalFrames = Int(((endTime - startTime) * Double(config.fps)).rounded())
    print("[swift-render] scene=\(args.sceneName) duration=\(duration)s range=\(startTime)-\(endTime)s fps=\(config.fps) size=\(Int(size.width * config.scale))×\(Int(size.height * config.scale))\(isPreview ? " (preview)" : "") frames=\(totalFrames) → \(args.out)")
    switch audioSource {
    case .file(let u): print("[swift-render] audio: \(u.path)")
    case .score(let sc): print(String(format: "[swift-render] audio: synthesized score (%d events)", sc.events.count))
    case .none: break
    }

    let start = Date()
    var span = RenderSpan(duration: duration, start: startTime, end: endTime, mux: args.rangeStart == nil)
    if args.progress == "json" {
        span.progress = { done, total in
            guard done % 10 == 0 || done == total else { return }
            let fps = Double(done) / max(1e-6, Date().timeIntervalSince(start))
            if let line = try? HostWire.encode(RenderProgressLine(frame: done, total: total, fps: (fps * 10).rounded() / 10)) {
                FileHandle.standardError.write(line)
            }
        }
    }
    if args.jobs > 1 && args.rangeStart == nil {
        try await renderParallel(jobs: args.jobs, scene: args.sceneName, duration: duration, fps: config.fps,
                                 audio: audioSource, out: outURL, argv: argv, progressJSON: args.progress == "json")
    } else {
        // Range renders are picture-only but still feed audio-reactive scenes their track.
        try await runner.render(recorder, outURL, span, audioSource, propsURL)
    }
    let elapsed = Date().timeIntervalSince(start)
    print(String(format: "[swift-render] done in %.1fs → %@", elapsed, args.out))
    if args.open { NSWorkspace.shared.open(outURL) }
}

